import React, { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import Navbar from './Navbar';
import Sidebar from './Sidebar';
import InventoryTable from './InventoryTable';
import UploadExcel from './UploadExcel';
import UserManagement from './UserManagement';
import { SkeletonCard, SkeletonPanel } from './Skeleton';
import { FiMonitor, FiCheckCircle, FiAlertTriangle, FiXCircle, FiDownload, FiPlus, FiUploadCloud } from 'react-icons/fi';
import { toast } from 'react-toastify';
import './Dashboard.css';

const API_URL = 'http://localhost:5000/api';

const Dashboard = () => {
  const { isAdmin } = useAuth();
  const [activeTab, setActiveTab] = useState('overview');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => localStorage.getItem('siqol_sb') === 'true');
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [invPreset, setInvPreset] = useState({ search: '', status: '', category: '', addId: 0 });
  const searchInputRef = useRef(null);
  const exportFilteredRef = useRef(null);

  useEffect(() => { fetchStats(); }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Ignore if typing in input/textarea
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'SELECT') {
        // Allow Escape to blur and close modals
        if (e.key === 'Escape') e.target.blur();
        return;
      }

      // '/' - Focus search
      if (e.key === '/') {
        e.preventDefault();
        searchInputRef.current?.focus();
      }

      // 'n' - New asset (admin only)
      if (e.key === 'n' && isAdmin()) {
        e.preventDefault();
        handleQuickAdd();
      }

      // 'g' + key navigation
      if (e.key === 'g') {
        let navKey = null;
        const navHandler = (ev) => {
          if (navKey) return;
          navKey = ev.key;
          if (navKey === 'o') { setActiveTab('overview'); toast.info('Navigated to Overview'); }
          else if (navKey === 'i') { setActiveTab('inventory'); toast.info('Navigated to Inventory'); }
          else if (navKey === 'u' && isAdmin()) { setActiveTab('users'); toast.info('Navigated to Users'); }
          else if (navKey === 'x' && isAdmin()) { setActiveTab('upload'); toast.info('Navigated to Upload'); }
          else if (navKey === 'h') {
            toast.info('Shortcuts: / search, n new asset, g+o/i/u/x navigate, h help', { autoClose: 5000 });
          }
          window.removeEventListener('keydown', navHandler);
        };
        window.addEventListener('keydown', navHandler, { once: true });
      }

      // '?' - Show help
      if (e.key === '?' && !e.shiftKey) {
        // Only trigger if not already in a g+ sequence
      }
      if (e.shiftKey && e.key === '/') {
        e.preventDefault();
        toast.info('Shortcuts: / search, n new asset, g+o/i/u/x navigate, ? help', { autoClose: 6000 });
      }

      // Escape - Close sidebar if open
      if (e.key === 'Escape' && sidebarOpen) {
        setSidebarOpen(false);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin, sidebarOpen]);

  const toggleCollapse = () => {
    const next = !sidebarCollapsed;
    setSidebarCollapsed(next);
    localStorage.setItem('siqol_sb', next.toString());
  };

  const openInventory = ({ search = '', status = '', category = '' } = {}) => {
    setInvPreset((p) => ({
      search,
      status,
      category,
      addId: p.addId,
    }));
    setActiveTab('inventory');
  };

  const handleGlobalSearch = (q) => {
    openInventory({ search: q });
  };

  // Expose search input ref to Navbar
  useEffect(() => {
    const navSearch = document.querySelector('.nav-search-input');
    if (navSearch) searchInputRef.current = navSearch;
  }, [activeTab]);

  const handleQuickAdd = () => {
    setInvPreset((p) => ({ ...p, addId: p.addId + 1 }));
    setActiveTab('inventory');
  };

  const fetchStats = async () => {
    try {
      const res = await axios.get(`${API_URL}/inventory/stats`);
      setStats(res.data);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const handleExport = async () => {
    // If viewing filtered results, export those instead
    if (activeTab === 'inventory' && exportFilteredRef.current) {
      exportFilteredRef.current();
      return;
    }
    // Otherwise export full dataset from server
    try {
      const res = await axios.get(`${API_URL}/inventory/export`, { responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a');
      a.href = url;
      a.download = 'SIQOL_Hardware_Inventory.xlsx';
      a.click();
      window.URL.revokeObjectURL(url);
      toast.success('Exported successfully');
    } catch { toast.error('Export failed'); }
  };

  const statCards = [
    { label: 'Total Assets', value: stats?.totalAssets || 0, icon: FiMonitor, color: 'accent', onClick: () => openInventory({}) },
    { label: 'Active', value: stats?.activeAssets || 0, icon: FiCheckCircle, color: 'success', onClick: () => openInventory({ status: 'Active' }) },
    { label: 'Maintenance', value: stats?.maintenanceAssets || 0, icon: FiAlertTriangle, color: 'warning', onClick: () => openInventory({ status: 'Maintenance' }) },
    { label: 'Retired', value: stats?.retiredAssets || 0, icon: FiXCircle, color: 'danger', onClick: () => openInventory({ status: 'Retired' }) },
  ];

  const renderOverview = () => {
    if (loading) return (
      <div className="overview">
        <div className="page-header">
          <div>
            <h2 className="page-title">Overview</h2>
            <p className="page-desc">Hardware asset summary</p>
          </div>
        </div>
        <div className="stat-grid">
          {Array.from({ length: 4 }).map((_, i) => <SkeletonCard key={i} />)}
        </div>
        <div className="panels-grid">
          {Array.from({ length: 3 }).map((_, i) => <SkeletonPanel key={i} />)}
        </div>
      </div>
    );

    return (
      <div className="overview">
        <div className="page-header">
          <div>
            <h2 className="page-title">Overview</h2>
            <p className="page-desc">Hardware asset summary</p>
          </div>
          <div className="header-actions">
            {isAdmin() ? (
              <button className="btn btn-primary" onClick={handleQuickAdd}>
                <FiPlus /> Add Asset
              </button>
            ) : null}
            {isAdmin() ? (
              <button className="btn btn-outline" onClick={() => setActiveTab('upload')}>
                <FiUploadCloud /> Upload
              </button>
            ) : null}
            <button className="btn btn-outline" onClick={() => openInventory({})}>
              <FiMonitor /> Inventory
            </button>
            <button className="btn btn-outline" onClick={handleExport} title={activeTab === 'inventory' ? 'Export filtered results' : 'Export all data'}>
              <FiDownload /> Export {activeTab === 'inventory' && <span className="export-badge">Filtered</span>}
            </button>
          </div>
        </div>

        <div className="stat-grid">
          {statCards.map((s, i) => {
            const Icon = s.icon;
            return (
              <div
                key={i}
                className="stat-card clickable"
                role="button"
                tabIndex={0}
                onClick={s.onClick}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') s.onClick();
                }}
              >
                <div className="stat-top">
                  <span className="stat-label">{s.label}</span>
                  <div className={`stat-icon-box ${s.color}`}><Icon /></div>
                </div>
                <div className="stat-value">{s.value}</div>
              </div>
            );
          })}
        </div>

        <div className="panels-grid">
          {/* Categories */}
          <div className="panel">
            <div className="panel-head">
              <h3 className="panel-title">Categories</h3>
            </div>
            <div className="panel-body">
              {stats?.categories && Object.entries(stats.categories).length > 0 ? (
                Object.entries(stats.categories).map(([cat, count]) => {
                  const pct = stats.totalAssets ? Math.round((count / stats.totalAssets) * 100) : 0;
                  return (
                    <div key={cat} className="bar-item">
                      <div className="bar-item-top">
                        <span className="bar-item-label">{cat}</span>
                        <span className="bar-item-value">{count}</span>
                      </div>
                      <div className="bar-track">
                        <div className="bar-fill accent" style={{ width: `${pct}%` }}></div>
                      </div>
                    </div>
                  );
                })
              ) : <p className="empty-text">No data</p>}
            </div>
          </div>

          {/* Departments */}
          <div className="panel">
            <div className="panel-head">
              <h3 className="panel-title">Departments</h3>
            </div>
            <div className="panel-body">
              {stats?.departments && Object.entries(stats.departments).length > 0 ? (
                Object.entries(stats.departments).map(([dept, count]) => {
                  const pct = stats.totalAssets ? Math.round((count / stats.totalAssets) * 100) : 0;
                  return (
                    <div key={dept} className="bar-item">
                      <div className="bar-item-top">
                        <span className="bar-item-label">{dept}</span>
                        <span className="bar-item-value">{count}</span>
                      </div>
                      <div className="bar-track">
                        <div className="bar-fill info" style={{ width: `${pct}%` }}></div>
                      </div>
                    </div>
                  );
                })
              ) : <p className="empty-text">No data</p>}
            </div>
          </div>

          {/* Status */}
          <div className="panel">
            <div className="panel-head">
              <h3 className="panel-title">Status</h3>
            </div>
            <div className="panel-body">
              {stats?.statusBreakdown && Object.entries(stats.statusBreakdown).length > 0 ? (
                Object.entries(stats.statusBreakdown).map(([status, count]) => {
                  const colorMap = { Active: 'success', Maintenance: 'warning', Retired: 'danger', 'In Storage': 'info' };
                  return (
                    <div key={status} className="status-row">
                      <div className="status-left">
                        <span className={`status-dot ${colorMap[status] || 'accent'}`}></span>
                        <span>{status}</span>
                      </div>
                      <span className="status-count">{count}</span>
                    </div>
                  );
                })
              ) : <p className="empty-text">No data</p>}
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'overview': return renderOverview();
      case 'inventory':
        return (
          <InventoryTable
            onUpdate={fetchStats}
            presetSearchTerm={invPreset.search}
            presetStatusFilter={invPreset.status}
            presetCategoryFilter={invPreset.category}
            openAddId={invPreset.addId}
            onExportFiltered={(exportFn) => { exportFilteredRef.current = exportFn; }}
          />
        );
      case 'upload': return isAdmin() ? <UploadExcel onUploadSuccess={fetchStats} /> : null;
      case 'users': return isAdmin() ? <UserManagement /> : null;
      default: return renderOverview();
    }
  };

  return (
    <div className="layout">
      <Sidebar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        isOpen={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        isCollapsed={sidebarCollapsed}
        onToggleCollapse={toggleCollapse}
      />
      <div className={`main ${sidebarCollapsed ? 'sb-collapsed' : ''}`}>
        <Navbar onToggleSidebar={() => setSidebarOpen(!sidebarOpen)} onGlobalSearch={handleGlobalSearch} />
        <div className="content">
          {renderContent()}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;