import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import {
  FiUsers, FiPlus, FiTrash2, FiShield, FiUser, FiX, FiSave,
  FiMail, FiCalendar
} from 'react-icons/fi';
import { SkeletonUserTable } from './Skeleton';
import './InventoryTable.css';
import './UserManagement.css';

const API_URL = 'http://localhost:5000/api';

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    username: '', password: '', fullName: '', email: '', role: 'user'
  });

  useEffect(() => { fetchUsers(); }, []);

  const fetchUsers = async () => {
    try {
      const res = await axios.get(`${API_URL}/auth/users`);
      setUsers(res.data);
    } catch (err) { toast.error('Error loading users'); }
    finally { setLoading(false); }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.username || !formData.password || !formData.fullName) {
      toast.error('Required fields missing');
      return;
    }
    try {
      await axios.post(`${API_URL}/auth/users`, formData);
      toast.success('User access granted');
      setShowModal(false);
      fetchUsers();
    } catch (err) { toast.error(err.response?.data?.message || 'Operation failed'); }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Revoke user access?')) return;
    try {
      await axios.delete(`${API_URL}/auth/users/${id}`);
      toast.success('Access revoked');
      fetchUsers();
    } catch (err) { toast.error(err.response?.data?.message || 'Operation failed'); }
  };

  if (loading) {
    return (
      <div className="inv-container-3d">
        <div className="inv-header-3d">
          <div className="inv-header-left">
            <div className="inv-header-icon" style={{ borderColor: 'rgba(168, 85, 247, 0.15)', background: 'rgba(168, 85, 247, 0.06)' }}>
              <FiUsers style={{ color: '#a855f7' }} />
            </div>
            <div>
              <h2 className="inv-title-3d">ACCESS CONTROL</h2>
              <p className="inv-count-3d">Loading users...</p>
            </div>
          </div>
        </div>
        <SkeletonUserTable rows={6} />
      </div>
    );
  }

  return (
    <div className="inv-container-3d">
      <div className="inv-header-3d">
        <div className="inv-header-left">
          <div className="inv-header-icon" style={{ borderColor: 'rgba(168, 85, 247, 0.15)', background: 'rgba(168, 85, 247, 0.06)' }}>
            <FiUsers style={{ color: '#a855f7' }} />
          </div>
          <div>
            <h2 className="inv-title-3d">ACCESS CONTROL</h2>
            <p className="inv-count-3d">{users.length} users registered</p>
          </div>
        </div>
        <button className="add-btn-3d" onClick={() => {
          setFormData({ username: '', password: '', fullName: '', email: '', role: 'user' });
          setShowModal(true);
        }}>
          <FiPlus /> <span>GRANT ACCESS</span>
        </button>
      </div>

      <div className="table-3d">
        <div className="table-glow-top" style={{ background: 'linear-gradient(90deg, transparent, rgba(168, 85, 247, 0.2), transparent)' }}></div>
        <table className="inv-table-3d">
          <thead>
            <tr>
              <th>OPERATOR</th>
              <th>USERNAME</th>
              <th>EMAIL</th>
              <th>CLEARANCE</th>
              <th>REGISTERED</th>
              <th>ACTIONS</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user, idx) => (
              <tr key={user.id} className="table-row-3d" style={{ animationDelay: `${idx * 0.05}s` }}>
                <td>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <div className={user.role === 'admin' ? 'um-icon-admin' : 'um-icon-user'}>
                      {user.role === 'admin' ? <FiShield /> : <FiUser />}
                    </div>
                    <span className="device-3d">{user.fullName}</span>
                  </div>
                </td>
                <td><span className="tag-3d">{user.username}</span></td>
                <td className="um-email-cell">
                  <FiMail size={13} /> {user.email || 'N/A'}
                </td>
                <td>
                  <span className={`status-badge-3d ${user.role === 'admin' ? 'badge-admin' : 'badge-operator'}`}>
                    <span className="badge-dot" style={{ background: user.role === 'admin' ? 'var(--danger)' : 'var(--success)' }}></span>
                    {user.role === 'admin' ? 'Admin' : 'Operator'}
                  </span>
                </td>
                <td className="um-date-cell">
                  <FiCalendar size={12} />
                  {user.createdAt ? new Date(user.createdAt).toLocaleDateString() : 'N/A'}
                </td>
                <td>
                  <button className="act-btn-3d delete" onClick={() => handleDelete(user.id)} title="Revoke Access">
                    <FiTrash2 />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="modal-overlay-3d" onClick={() => setShowModal(false)}>
          <div className="modal-3d" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header-3d">
              <div className="modal-title-group">
                <div className="modal-icon-3d" style={{ borderColor: 'rgba(168, 85, 247, 0.15)', background: 'rgba(168, 85, 247, 0.06)' }}>
                  <FiPlus style={{ color: '#a855f7' }} />
                </div>
                <div>
                  <h3>GRANT USER ACCESS</h3>
                  <span className="modal-sub">Register new system operator</span>
                </div>
              </div>
              <button className="modal-close-3d" onClick={() => setShowModal(false)}><FiX /></button>
            </div>
            <form onSubmit={handleSubmit} className="modal-form-3d">
              <div className="form-grid-3d">
                <div className="field-3d"><label>FULL NAME *</label><input type="text" value={formData.fullName} onChange={(e) => setFormData({ ...formData, fullName: e.target.value })} required /></div>
                <div className="field-3d"><label>USERNAME *</label><input type="text" value={formData.username} onChange={(e) => setFormData({ ...formData, username: e.target.value })} required /></div>
                <div className="field-3d"><label>PASSWORD *</label><input type="password" value={formData.password} onChange={(e) => setFormData({ ...formData, password: e.target.value })} required /></div>
                <div className="field-3d"><label>EMAIL</label><input type="email" value={formData.email} onChange={(e) => setFormData({ ...formData, email: e.target.value })} /></div>
                <div className="field-3d">
                  <label>CLEARANCE LEVEL</label>
                  <select value={formData.role} onChange={(e) => setFormData({ ...formData, role: e.target.value })}>
                    <option value="user">Operator</option>
                    <option value="admin">Administrator</option>
                  </select>
                </div>
              </div>
              <div className="modal-actions-3d">
                <button type="button" className="cancel-3d" onClick={() => setShowModal(false)}>CANCEL</button>
                <button type="submit" className="save-3d"><FiSave /> AUTHORIZE</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserManagement;